(()=>{if(document.getElementById("jf-3d-poster-styles"))return;let e=document.createElement("style");e.id="jf-3d-poster-styles",e.textContent=`
            .cardBox { perspective: 1200px; }
            .cardScalable { transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94); transform-style: preserve-3d; will-change: transform; position: relative; }
            .card.tilt-active .cardScalable { transition: transform 0.1s ease-out; }
            .cardScalable::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: radial-gradient(circle at var(--mouseX, 50%) var(--mouseY, 50%), rgba(255, 255, 255, 0.15) 0%, transparent 60%); opacity: 0; transition: opacity 0.4s ease; pointer-events: none; z-index: 10; }
            .card.tilt-active .cardScalable::after { opacity: 1; }
        `,document.head.appendChild(e)})(),document.addEventListener("mousemove",e=>{let t=e.target.closest(".card");if(!t)return;let a=t.querySelector(".cardScalable");if(!a)return;t.classList.add("tilt-active");let r=a.getBoundingClientRect(),s=e.clientX-r.left,i=e.clientY-r.top,l=r.width/2,o=r.height/2,n=s/r.width*100,c=i/r.height*100;a.style.transform=`rotateX(${-((i-o)/o*12)}deg) rotateY(${(s-l)/l*12}deg) scale3d(1.05, 1.05, 1.05)`,a.style.setProperty("--mouseX",`${n}%`),a.style.setProperty("--mouseY",`${c}%`)}),document.addEventListener("mouseout",e=>{let t=e.target.closest(".card");if(t&&!t.contains(e.relatedTarget)){t.classList.remove("tilt-active");let a=t.querySelector(".cardScalable");a&&(a.style.transform="rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)")}});
